package com.leochaddad.capacitor.referrer;

import android.content.Context;
import android.os.RemoteException;
import com.android.installreferrer.api.InstallReferrerClient;
import com.android.installreferrer.api.InstallReferrerStateListener;
import com.android.installreferrer.api.ReferrerDetails;
import com.getcapacitor.JSObject;
import com.getcapacitor.Logger;

public class CapacitorReferrer {

    public interface ReferrerCallback {
        void onSuccess(JSObject result);
        void onError(String error);
    }

    public void getReferrerDetails(Context context, ReferrerCallback callback) {
        InstallReferrerClient referrerClient = InstallReferrerClient.newBuilder(context).build();

        referrerClient.startConnection(new InstallReferrerStateListener() {
            @Override
            public void onInstallReferrerSetupFinished(int responseCode) {
                switch (responseCode) {
                    case InstallReferrerClient.InstallReferrerResponse.OK:
                        try {
                            ReferrerDetails response = referrerClient.getInstallReferrer();
                            JSObject result = new JSObject();
                            result.put("referrerUrl", response.getInstallReferrer());
                            result.put("referrerClickTimestampSeconds", response.getReferrerClickTimestampSeconds());
                            result.put("appInstallTimestampSeconds", response.getInstallBeginTimestampSeconds());
                            result.put("referrerClickTimestampServerSeconds", response.getReferrerClickTimestampServerSeconds());
                            result.put("appInstallTimestampServerSeconds", response.getInstallBeginTimestampServerSeconds());
                            result.put("installVersion", response.getInstallVersion());
                            result.put("googlePlayInstantParam", response.getGooglePlayInstantParam());

                            referrerClient.endConnection();
                            callback.onSuccess(result);
                        } catch (RemoteException e) {
                            Logger.error("CapacitorReferrer", "RemoteException: " + e.getMessage(), e);
                            referrerClient.endConnection();
                            callback.onError("Failed to get referrer details: " + e.getMessage());
                        }
                        break;
                    case InstallReferrerClient.InstallReferrerResponse.FEATURE_NOT_SUPPORTED:
                        Logger.error("CapacitorReferrer", "Install Referrer not supported", null);
                        referrerClient.endConnection();
                        callback.onError("Install Referrer API not supported on this device");
                        break;
                    case InstallReferrerClient.InstallReferrerResponse.SERVICE_UNAVAILABLE:
                        Logger.error("CapacitorReferrer", "Play Store service unavailable", null);
                        referrerClient.endConnection();
                        callback.onError("Play Store service is unavailable");
                        break;
                    default:
                        Logger.error("CapacitorReferrer", "Unknown response code: " + responseCode, null);
                        referrerClient.endConnection();
                        callback.onError("Unknown error occurred (code: " + responseCode + ")");
                        break;
                }
            }

            @Override
            public void onInstallReferrerServiceDisconnected() {
                Logger.warn("CapacitorReferrer", "Install Referrer service disconnected");
                callback.onError("Install Referrer service disconnected");
            }
        });
    }
}
